const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '自由落体示意' },
      { kind: 'text', payload: '由静止释放：v₀ = 0' },
      { kind: 'text', payload: 'v' },
      { kind: 'text', payload: 'g' },
      { kind: 'text', payload: 'v 与 g 的方向均竖直向下' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var cx = W * 0.5;
    var r = Math.min(W * 0.12, 28);
    var ballY = H * 0.24;
    var vX = cx + r * 0.5;
    var gX = cx - r * 0.5;
    var vTip = ballY + H * 0.40;
    var gTip = ballY + H * 0.24;
    var traj = [['M', cx, ballY - r - 26], ['L', cx, ballY + H * 0.50]];
    var vArrow = visualSdk.arrow(vX, ballY, vX, vTip, {});
    var gArrow = visualSdk.arrow(gX, ballY, gX, gTip, {});
    return {
      schemaVersion: 1,
      sceneId: 'free-fall',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'traj', commands: traj },
        { id: 'ball', commands: visualSdk.circle(cx, ballY, r) },
        { id: 'vArrow', commands: vArrow },
        { id: 'gArrow', commands: gArrow }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'traj', fill: '#9AA7B8', stroke: { width: 1.5, cap: 'round', dash: [7, 7] } },
          { type: 'path', pathId: 'ball', fill: '#26354A', stroke: { width: 2 } },
          { type: 'path', pathId: 'vArrow', fill: '#C0392B', stroke: { width: 2, cap: 'round', join: 'round' } },
          { type: 'path', pathId: 'gArrow', fill: '#1F6FB2', stroke: { width: 2, cap: 'round', join: 'round' } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: cx, y: H * 0.05 }, hAlign: 'center', vAlign: 'top', color: '#26354A' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: cx, y: ballY - r - 28 }, hAlign: 'center', vAlign: 'bottom', color: '#26354A' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: vX + 12, y: ballY + H * 0.30 }, hAlign: 'left', vAlign: 'middle', color: '#C0392B' },
          { type: 'label', contentId: metrics[3].contentId, anchor: { x: gX - 12, y: ballY + H * 0.15 }, hAlign: 'right', vAlign: 'middle', color: '#1F6FB2' },
          { type: 'label', contentId: metrics[4].contentId, anchor: { x: cx, y: H * 0.94 }, hAlign: 'center', vAlign: 'middle', color: '#26354A' }
        ]
      }
    };
  }
};
